// Fontshare
const css = await (await fetch("https://api.fontshare.com/v2/css?f[]=zodiak@400,700,300&f[]=switzer@400,500,700&display=swap")).text();
const blocks = css.split('@font-face').slice(1);
let fam = null;
for (const b of blocks) {
  const f = /font-family: '([^']+)'/.exec(b)[1];
  const w = /font-weight: (\d+)/.exec(b)[1];
  const style = /font-style: (\w+)/.exec(b)[1];
  if (style !== 'normal') continue;
  const u = /url\('\/\/([^']+\.woff2)'/.exec(b)[1];
  await grab('https://' + u, `${f.toLowerCase()}-${w}.woff2`);
}
// Google IBM Plex Mono
const g = await (await fetch('https://fonts.googleapis.com/css2?family=IBM+Plex+Mono:wght@400;500&display=swap', { headers: { 'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 Chrome/120 Safari/537.36' } })).text();
const parts = g.split('@font-face').slice(1).filter(b => /latin/.test(b) === false ? false : true);
const seen = new Set();
for (const b of g.split('@font-face').slice(1)) {
  const w = /font-weight: (\d+)/.exec(b)?.[1];
  const u = /url\((https:[^)]+\.woff2)\)/.exec(b)?.[1];
  const range = /unicode-range: ([^;]+)/.exec(b)?.[1] || '';
  if (!u || !w) continue;
  if (!range.includes('U+0000-00FF')) continue;      // latin subset only
  const k = w; if (seen.has(k)) continue; seen.add(k);
  await grab(u, `plexmono-${w}.woff2`);
}
