import { chromium } from 'playwright';
const url = 'http://localhost:4173/';
const b = await chromium.launch();
const errs = [];
async function shoot(w, h, tag, opts = {}) {
  const ctx = await b.newContext({ viewport: { width: w, height: h }, deviceScaleFactor: 1 });
  const p = await ctx.newPage();
  p.on('console', (m) => { if (m.type() === 'error') errs.push(`[${tag}] ${m.text()}`); });
  p.on('pageerror', (e) => errs.push(`[${tag}] pageerror ${e.message}`));
  p.on('requestfailed', (r) => errs.push(`[${tag}] 404? ${r.url()} ${r.failure()?.errorText}`));
  await p.goto(url, { waitUntil: 'networkidle' });
  // scroll the whole page so lazy images + reveals + rail progress resolve
  await p.evaluate(async () => {
    const step = window.innerHeight * 0.6;
    for (let y = 0; y < document.body.scrollHeight; y += step) {
      window.scrollTo(0, y);
      await new Promise((r) => setTimeout(r, 90));
    }
    window.scrollTo(0, 0);
    await new Promise((r) => setTimeout(r, 400));
  });
  await p.waitForTimeout(700);
  if (opts.before) await opts.before(p);
  await p.screenshot({ path: `.shots/${tag}-full.png`, fullPage: true });
  const oflow = await p.evaluate(() => document.documentElement.scrollWidth - window.innerWidth);
  console.log(tag, 'overflowPx=', oflow);
  await ctx.close();
}
await shoot(1440, 900, 'desk');
await shoot(390, 844, 'mob');
console.log(errs.length ? errs.join('\n') : 'no console errors');
await b.close();
